class Solution { public:string repeatLimitedString(string s,int repeatLimit){int count[26]={};for(char ch:s)++count[ch-'a'];string answer;int current=25;while(current>=0){while(current>=0&&!count[current])--current;if(current<0)break;int take=min(count[current],repeatLimit);answer.append(take,'a'+current);count[current]-=take;if(!count[current])continue;int separator=current-1;while(separator>=0&&!count[separator])--separator;if(separator<0)break;answer+='a'+separator;--count[separator];}return answer;} };
